csui.define('csui/utils/commands/unrequest.reservation',[
  "csui/lib/underscore",
  "csui/lib/jquery",
  "module",
  "i18n!csui/utils/commands/nls/localized.strings",
  "csui/utils/url",
  "csui/utils/base",
  "csui/utils/commandhelper",
  "csui/utils/commands/node",
  "smart/dialogs/modal.alert/modal.alert",
  "csui/models/command",
], function (
  _,
  $,
  module,
  lang,
  Url,
  base,
  CommandHelper,
  NodeCommand,
  ModalAlert,
  CommandModel
) {
  "use strict";

  var config = _.extend({}, module.config());

  var UnrequestReservationCommand = NodeCommand.extend({

    defaults: {
      command: "UnrequestReservation",
      signature: "UnrequestReservation",
      command_key: ["unrequestreservation", "UnrequestReservation"],
      name: lang.CommandNameUnrequestReservation,
      verb: lang.CommandVerbUnrequestReservation,
    },

    enabled: function (status, options) {
      var self = this;
      this.status = status;
      this.options = options || {};
      var node = CommandHelper.getJustOneNode(status);
      var context = status.context;
      var current_user = context.getModel('user');

      if (!(node && current_user)){
        return false;
      }

      if (current_user.has("id")) {

        if (node.has("reserved_user_id") &&
            (node.get("reserved_user_id") === current_user.get("id"))) {
          // User's request automatically gets deleted when the user reserved the node in backend.
          return false;
        }

        // is_request_in_queue will be defined on the node model only after any
        // request/unrequest command execution locally on the client.
        // If true, the request has already made and unrequestreservation should be displayed
        // If false, the request has been canceled and unrequestreservation should not be displayed
        if (node.has("is_request_in_queue") && (node.get("is_request_in_queue") !== undefined)) {
          return node.get("is_request_in_queue");
        }

      } else {
        // If no user defined, follow the prototype setting.
        // Only happens when the nodestable is loaded first time
      }

      return CommandModel.prototype.enabled.apply(this, arguments);
    },

    execute: function (status, options) {
      var node = CommandHelper.getJustOneNode(status);
      var self = this;
      this.options = options || {};
      this._deferred = $.Deferred();
      this.connector =
        this.options.connector ||
        (status.collection && status.collection.connector) ||
        (status.container && status.container.connector) ||
        node.connector;
      this.model = node;

      csui.require([
        'csui/controls/globalmessage/globalmessage'
      ], function (GlobalMessage) {

        var baseUrl = new Url(self.connector.connection.url).getApiBase("v2");
        self._confirmModal()
          .then(function (answer) {
            if (answer) {
              // Send a request for reservation
              var executeOptions = {
                url: Url.combine(baseUrl, "reservemanagement/nodes", node.get("id")),
                type: "DELETE",
              };

              self.connector.makeAjaxCall(executeOptions)
                .done(function () {
                  GlobalMessage.showMessage(
                    "success",
                    lang.UnrequestReservationSuccessMessage
                  );
                  self.model.set({ is_request_in_queue: false });
                  self._deferred.resolve();
                }) // makeAjaxCall.done()
                .fail(function (error) {
                  GlobalMessage.showMessage(
                    "error",
                    lang.UnrequestReservationFailMessage,
                    error.responseJSON.error
                  );
                  self._deferred.reject();
                }); // makeAjaxCall.fail()
            }
          });
      }, self._deferred.reject);
      return self._deferred.promise();
    },

    _formatConfirmationResponse: function () {
      var modalMessage;
      var modalTitle = lang.ConfirmUnrequestReservationTitle;
      modalMessage = _.str.sformat(lang.ConfirmUnrequestReservationBody, this.model.get("name"));

      return { message: modalMessage, title: modalTitle };
    },

    _confirmModal: function () {
      var self = this;
      self._confirmationDeferred = $.Deferred();

      var confirmationData = self._formatConfirmationResponse();

      ModalAlert.confirmQuestion(
        confirmationData.message,
        confirmationData.title,
        {
          buttons: {
            showYes: true,
            showNo: true
          },
        }
      ).always(function (answer) {
        if (answer) {
          self._confirmationDeferred.resolve(true);
        } else if (answer !== undefined) {
          self._confirmationDeferred.resolve(false);
        }
      });
      return self._confirmationDeferred.promise();
    }
  });

  return UnrequestReservationCommand;
});